#!/usr/bin/env python3
"""omics/hic_3d_contact — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "hic_3d_contact"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'hic_3d_contact', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Hi-C contact matrix 处理:pairtools → cooler.cload pairs → balance → dump。
    host_env=hic(cooler + pairtools)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pairs_path = payload.get("pairs_path") or payload.get("input_pairs")
    chrom_sizes = payload.get("chrom_sizes")
    bin_size = int(payload.get("bin_size", 10000))
    out_cool = payload.get("out_cool") or _tempfile.NamedTemporaryFile(suffix=".cool", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "cooler", "bin_size": bin_size, "out_cool": out_cool}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not pairs_path or not _os.path.isfile(pairs_path):
        return {"ok": False, "error": "需要 pairs_path", "diagnostics": diagnostics}
    if not chrom_sizes or not _os.path.isfile(chrom_sizes):
        return {"ok": False, "error": "需要 chrom_sizes 文件", "diagnostics": diagnostics}
    t0 = _time.time()
    # 1) cload pairs to cool
    r1 = run_tool(["cooler", "cload", "pairs", f"{chrom_sizes}:{bin_size}",
                   pairs_path, out_cool],
                  timeout=int(payload.get("cload_timeout_s", 3600)))
    if not r1["ok"]:
        return {"ok": False, "error": "cooler cload 失败",
                "stderr": r1.get("stderr", "")[-300:], "diagnostics": diagnostics}
    # 2) balance
    r2 = run_tool(["cooler", "balance", out_cool], timeout=600)
    diagnostics["balance"] = {"rc": r2.get("returncode")}
    # 3) info
    r3 = run_tool(["cooler", "info", out_cool], timeout=30)
    info_lines = r3["stdout"].strip().splitlines() if r3["ok"] else []
    n_contacts = 0
    for ln in info_lines:
        if "sum:" in ln:
            try: n_contacts = int(ln.split(":")[1].strip()); break
            except (ValueError, IndexError): pass
    return {"ok": True, "skill_id": SKILL, "matrix_path": out_cool,
            "n_cells_post_qc": 0, "cluster_sizes": {}, "marker_genes_per_cluster": {},
            "n_contacts": n_contacts,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "info_lines": info_lines[:20]}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
